def add(self, key, data=None):
    '''
    Add a key, data pair.
    '''
    if data is None:
        data = key

    self.size += 1
    node = self.NodeClass(key, data)
    curr_node = self.root
    if curr_node is None:
        self.root = node
        return
    while True:
        if node < curr_node:
            if curr_node.left is None:
                curr_node.left = node
                break
            curr_node = curr_node.left
        elif node > curr_node:
            if curr_node.right is None:
                curr_node.right = node
                break
            curr_node = curr_node.right
        elif self.unique:
            raise ValueError("Cannot insert non-unique value")
        else:  # add data to node
            curr_node.data.extend(node.data)
            curr_node.data = sorted(curr_node.data)
            return

def items(self):
    """Like :meth:`dict.items`."""

    for card in self._cards:
        yield card.keyword, None if card.value == UNDEFINED else card.value

def items(self):
    '''
    Return a list of key, data tuples.
    '''
    result = OrderedDict()
    for node in self._nodes:
        if node.key in result:
            result[node.key].append(node.value)
        else:
            result[node.key] = [node.value]
    return result.items()

def remove(self, key, data=None):
    '''
    Remove data from the given key.
    '''
    if data is not None:
        item = Node(key, data)
        try:
            self._nodes.remove(item)
        except ValueError:
            return False
        return True
    items = list(self._nodes.irange(key, key))
    for item in items:
        self._nodes.remove(item)
    return bool(items)

def set(self, names):
    """Set value of include/exclude attribute to ``names``.

